// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

library SafeCast {
    error Overflow(uint256 amount);

    function encodeUInt128(uint256 amount) internal pure returns (uint128) {
        if (amount > type(uint128).max) {
            revert Overflow(amount);
        }
        return uint128(amount);
    }

    function encodeUInt112(uint256 amount) internal pure returns (uint112) {
        if (amount > type(uint112).max) {
            revert Overflow(amount);
        }
        return uint112(amount);
    }

    function encodeUInt96(uint256 amount) internal pure returns (uint96) {
        if (amount > type(uint96).max) {
            revert Overflow(amount);
        }
        return uint96(amount);
    }

    function encodeUInt32(uint256 amount) internal pure returns (uint32) {
        if (amount > type(uint32).max) {
            revert Overflow(amount);
        }
        return uint32(amount);
    }

    function encodeUInt16(uint256 amount) internal pure returns (uint16) {
        if (amount > type(uint16).max) {
            revert Overflow(amount);
        }
        return uint16(amount);
    }
}

src/libraries/CompoundedInterest.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

import {FixedPointMathLib} from "solmate/utils/FixedPointMathLib.sol";
import {wadExp} from "solmate/utils/SignedWadMath.sol";

library CompoundedInterest {
    using FixedPointMathLib for uint256;

    uint96 internal constant ONE_YEAR = 365 days;

    /// @notice Calculate the continuously compounded interest
    /// given by: Pₜ = P₀eʳᵗ
    /// @param principal The principal amount, in 18 decimal places
    /// @param elapsedSecs The elapsed seconds
    /// @param interestRatePerYear The interest rate per year, in 18 decimal places
    function continuouslyCompounded(
        uint256 principal,
        uint256 elapsedSecs,
        uint96 interestRatePerYear
    ) internal pure returns (uint256 result) {
        return
            principal.mulWadDown(
                uint256(wadExp(int256((interestRatePerYear * elapsedSecs) / ONE_YEAR)))
            );
    }
}

